'use client';

import * as React from 'react';
import './region.css';

/* ─────────────────────────────────────────────────────────
 * REGION (Kamui 04 §7, the medium demo's .region)
 *
 * rest    a sunk well; the head names it, says the rule it carries, counts what is inside
 * over    a block is dragged above it: green fill, 1 pt ring, the rule reads "drop to mark tasks done"
 *         (fill and ring cross-fade on settle); the dropped block lands on the object spring (the host's)
 * dim     an in-place lens has no match inside: .35
 * past    it did not exist at the scrubbed time: 0, and it takes no pointer
 * lens    a pinned lens: a frosted plate listing its matches as rows
 * rename  the name becomes a field; Enter commits, Escape restores
 * Radius: hero (30) when the short side is at least 240, else card (24).
 * ───────────────────────────────────────────────────────── */

export interface RegionProps extends Omit<React.HTMLAttributes<HTMLDivElement>, 'children'> {
  /** The region's name; its rule follows from it (Done, To do, Doing, a date, anything else tags). */
  name: string;
  /** What the rule does, as the head says it: "marks tasks done", "tags them #poster". */
  rule?: string;
  /** What the rule does to a block dropped now: "drop to mark tasks done". Shown while over. */
  dropRule?: string;
  /** Blocks inside. */
  count?: number;
  over?: boolean;
  dim?: boolean;
  past?: boolean;
  /** A pinned lens: a frosted plate whose body lists rows. */
  lens?: boolean;
  /** Renaming: the name is a field. */
  renaming?: boolean;
  onRename?: (name: string) => void;
  onRenameCancel?: () => void;
  /** The region's size, to pick its radius from the ladder. */
  width: number;
  height: number;
  /** A pinned lens region's rows. */
  children?: React.ReactNode;
}

/** A drawn rectangle with a name that carries a rule. Placement is meaning, and reversible. */
export const Region = React.forwardRef<HTMLDivElement, RegionProps>(function Region(
  { name, rule, dropRule, count, over, dim, past, lens, renaming, onRename, onRenameCancel, width, height, className, style, children, ...props },
  ref,
) {
  const bigAt = typeof window === 'undefined' ? 240 : parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--mu-region-big-at')) || 240;
  const [draft, setDraft] = React.useState(name);
  React.useEffect(() => { if (renaming) setDraft(name); }, [renaming, name]);
  return (
    <div
      ref={ref}
      role="group"
      aria-label={name ? `Region ${name}${rule ? `, ${rule}` : ''}` : 'Unnamed region'}
      data-over={over ? '' : undefined}
      data-dim={dim ? '' : undefined}
      data-past={past ? '' : undefined}
      data-lens={lens ? '' : undefined}
      data-big={Math.min(width, height) >= bigAt ? '' : undefined}
      className={className ? `mu-region ${className}` : 'mu-region'}
      style={{ width, height, ...style }}
      {...props}
    >
      <div className="mu-region-head">
        {renaming ? (
          <input
            autoFocus
            aria-label="Region name"
            className="mu-region-name"
            value={draft}
            placeholder="name this region"
            onChange={(e) => setDraft(e.target.value)}
            onBlur={() => onRename?.(draft.trim())}
            onKeyDown={(e) => {
              if (e.key === 'Enter') { e.preventDefault(); onRename?.(draft.trim()); }
              if (e.key === 'Escape') { e.preventDefault(); onRenameCancel?.(); }
            }}
          />
        ) : (
          <span className="mu-region-name" data-placeholder="name this region" data-empty={name ? undefined : ''}>{name}</span>
        )}
        <span className="mu-region-rule mu-type-label engraved">{over && dropRule ? dropRule : rule}</span>
        {count ? <span className="mu-region-count">{count}</span> : null}
      </div>
      {lens && <div className="mu-region-body">{children}</div>}
    </div>
  );
});

export interface RegionRowProps extends React.HTMLAttributes<HTMLDivElement> {
  checked?: boolean;
  /** A leading dimple (a Dimple) for task rows. */
  lead?: React.ReactNode;
  /** A trailing engraving: the day, a count. */
  meta?: React.ReactNode;
}

/** A row in a pinned lens region. Ticking its dimple ticks the real block. */
export function RegionRow({ checked, lead, meta, className, children, ...props }: RegionRowProps) {
  return (
    <div tabIndex={0} data-checked={checked ? '' : undefined} className={className ? `mu-region-row type-ui ${className}` : 'mu-region-row type-ui'} {...props}>
      {lead}
      <span className="mu-region-row-text">{children}</span>
      {meta && <span className="mu-region-row-meta mu-type-label engraved">{meta}</span>}
    </div>
  );
}

@import "../tokens.css";

/* Region (Kamui 04 §7, the medium demo's .region). Its look is the region recipe (--mu-r-region-*). */
.mu-region {
  position: relative;
  box-sizing: border-box;
  border-radius: var(--mu-r-region-self-radius);
  background: var(--mu-r-region-self-background);
  box-shadow: var(--mu-r-region-self-shadow);
  transition:
    background var(--mu-spring-settle-d) var(--mu-spring-settle),
    box-shadow var(--mu-spring-settle-d) var(--mu-spring-settle),
    opacity var(--mu-spring-settle-d) var(--mu-spring-settle);
}
.mu-region[data-big] { border-radius: var(--mu-r-region-self-radius-big); }
/* Over: a block is dragged above it. The drop target lights and the rule says what the drop will do. */
.mu-region[data-over] {
  background: var(--mu-r-region-self-over-background);
  box-shadow: var(--mu-r-region-self-over-shadow);
}
.mu-region[data-over] .mu-region-rule { color: var(--mu-r-region-rule-over-color); text-shadow: none; }
.mu-region[data-dim] { opacity: var(--mu-r-region-self-dim); }
.mu-region[data-past] { opacity: 0; pointer-events: none; }
/* A pinned lens: a frosted plate that lists its matches instead of a well that holds blocks. */
.mu-region[data-lens] {
  background: var(--mu-r-region-self-lens-background);
  box-shadow: var(--mu-raise-lite);
  -webkit-backdrop-filter: blur(var(--mu-r-region-lens-blur));
  backdrop-filter: blur(var(--mu-r-region-lens-blur));
}
@media (prefers-reduced-transparency: reduce) {
  .mu-region[data-lens] { background: var(--mu-frost-opaque); -webkit-backdrop-filter: none; backdrop-filter: none; }
}
.mu-region-head {
  position: absolute;
  inset: var(--mu-zero) var(--mu-zero) auto var(--mu-zero);
  box-sizing: border-box;
  height: var(--mu-r-region-head-height);
  padding: var(--mu-r-region-head-pad-top) var(--mu-r-region-head-pad-x) var(--mu-zero);
  display: flex;
  align-items: baseline;
  gap: var(--mu-r-region-head-gap);
  cursor: grab;
}
.mu-region-name { min-width: 20px; white-space: nowrap; font: var(--mu-r-region-name-font); letter-spacing: var(--mu-r-region-name-tracking); color: var(--mu-ink); outline: none; }
.mu-region-name:empty::before, .mu-region-name[data-empty]::before { content: attr(data-placeholder); color: var(--mu-ink3); font-weight: var(--mu-r-region-name-placeholder-weight); }
input.mu-region-name {
  border: 0;
  padding: var(--mu-zero);
  margin: var(--mu-zero);
  background: transparent;
  cursor: text;
  caret-color: var(--mu-green-deep);
  field-sizing: content;
}
input.mu-region-name::placeholder { color: var(--mu-ink3); font-weight: var(--mu-r-region-name-placeholder-weight); }
.mu-region-rule { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; transition: color var(--mu-spring-settle-d) var(--mu-spring-settle); }
.mu-region-count { font: var(--mu-r-region-count-font); color: var(--mu-ink3); }
.mu-region-body {
  position: absolute;
  left: var(--mu-r-region-body-inset);
  right: var(--mu-r-region-body-inset);
  top: var(--mu-r-region-body-top);
  bottom: var(--mu-r-region-body-inset);
  overflow: hidden;
}

/* A row in a pinned lens region. */
.mu-region-row {
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: var(--mu-region-row-gap);
  padding: var(--mu-region-row-pad-y) var(--mu-region-row-pad-x);
  border-radius: var(--mu-radius-row);
  color: var(--mu-ink);
  cursor: pointer;
  transition: background var(--mu-spring-settle-d) var(--mu-spring-settle), box-shadow var(--mu-spring-settle-d) var(--mu-spring-settle);
}
.mu-region-row:hover { background: var(--mu-row-hover); box-shadow: var(--mu-raise-sm); }
.mu-region-row:focus-visible { outline: var(--mu-focus-width) solid var(--mu-focus); outline-offset: var(--mu-focus-offset); }
.mu-region-row > .mu-region-row-text { flex: 1; min-width: 0; }
.mu-region-row[data-checked] > .mu-region-row-text { color: var(--mu-ink3); text-decoration: line-through; }
.mu-region-row > .mu-region-row-meta { margin-left: auto; padding-top: var(--mu-r-region-row-meta-top); }
.mu-region-row .mu-dimple:not([data-ghost]) { width: var(--mu-region-row-dimple); height: var(--mu-region-row-dimple); border-radius: var(--mu-cue-ghost-radius); }
.mu-region-empty { padding: var(--mu-r-region-empty-pad-y) var(--mu-r-region-empty-pad-x); color: var(--mu-ink2); }
